cd "$INPUT_DIR" && python3 -c "
import openpyxl,glob
for f in glob.glob('*.xlsx'):
    wb=openpyxl.load_workbook(f,data_only=True)
    for ws in wb:
        for r in ws.iter_rows():
            for c in r:
                v=c.value
                if isinstance(v,str) and ('-24' in v or 'FY24' in v or '2024' in v):
                    print(f,ws.title,c.coordinate,repr(v))
"
